// Package codegen generates the route registration code consumed by the
// server. Generated files are build artifacts — never hand-edited, never
// committed. Generation happens at build time only; the production request
// path executes plain pre-registered Go routes with no scanning,
// reflection, or Node involvement.
package codegen

import (
	"fmt"
	"go/format"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"

	"go-meta/internal/routing"
)

// header is stamped on every generated file.
const header = "// Code generated by go-meta route generator. DO NOT EDIT."

// RoutesFile generates the Go source of the routes registration package
// for the discovered route set. Output is deterministic for identical
// inputs: routes are emitted in manifest (path-sorted) order and passed
// through go/format, so bytes are stable across runs.
//
// SSR routes reference the templ-generated package `go-meta/app`: the
// generated source imports it and exposes its Page symbol so the server
// can render the compiled page (C04). The manifest carries only paths
// and modes; symbol wiring lives here at generation time — no reflection.
// RoutesFile renders a manifest into the generated routes package source.
// The generated package imports each SSR route's templ-generated package
// (see templImportPath) and exposes RegisterRoutes plus SSRPage so the
// server registers pre-generated route data at startup — no runtime
// discovery, no reflection, no filesystem access in the request path.
//
// Symbol verification: before emitting bindings, the generator reads each
// SSR page's .templ source from fsys and confirms it declares the expected
// component (see expectedSymbol). A missing or misnamed symbol fails
// generation with an error naming the source file — C09's "build error
// names source file; no runtime panic" contract.
func RoutesFile(m routing.Manifest) ([]byte, error) {
	// C09: before emitting bindings, the generator verifies each SSR page's
	// .templ source declares the expected component, so a missing or misnamed
	// symbol fails generation with an error naming the source file instead of
	// surfacing as an undefined reference (or runtime panic) later.
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\n\npackage routes\n\n")
	b.WriteString("import (\n")
	b.WriteString("\t\"fmt\"\n")
	b.WriteString("\t\"github.com/a-h/templ\"\n")
	b.WriteString("\t\"go-meta/internal/routing\"\n")
	for _, r := range m.Routes {
		if r.Mode != routing.ModeSSR {
			continue
		}
		fmt.Fprintf(&b, "\tpage%d %q\n", ssrIndex(r, m), templImportPath(r))
	}
	layouts := layoutSources(m)
	for _, l := range layouts {
		fmt.Fprintf(&b, "\tlayout%d %q\n", layoutIndex(layouts, l), layoutImportPath(l))
	}
	b.WriteString(")\n\n")

	b.WriteString("// RegisterRoutes is generated from the app tree at build time.\n")
	b.WriteString("func RegisterRoutes() []routing.Route {\n")
	b.WriteString("\treturn []routing.Route{\n")
	for _, r := range m.Routes {
		writeRouteLiteral(&b, r)
	}
	b.WriteString("\t}\n}\n\n")

	// SSRPage resolves each SSR route's templ-generated page symbol from
	// its compiled package. Symbols follow the file convention:
	// <dir>/page.templ declares templ <PascalDir>() — Page, About. The
	// mapping is emitted per route at generation time (no reflection, no
	// runtime lookup).
	//
	// A missing or misnamed component symbol is reported at generation
	// time as an actionable error naming the source file (C09), and the
	// generated fallback returns a typed error instead of panicking —
	// no runtime nil-pointer or panic path exists for missing bindings.
	b.WriteString("// SSRPage returns the templ-generated page component for an SSR route,\n")
	b.WriteString("// composed with its layout chain (D06). Route.Layouts is ordered\n")
	b.WriteString("// outermost to innermost; composition wraps from the innermost\n")
	b.WriteString("// layout outward, so the outermost layout owns the HTML document.\n")
	b.WriteString("func SSRPage(r routing.Route) (templ.Component, error) {\n")
	for _, r := range m.Routes {
		if r.Mode != routing.ModeSSR {
			continue
		}
		fmt.Fprintf(&b, "\tif r.ID == %q {\n", r.ID)
		// Compose layouts innermost-first so the outermost layout owns the
		// document: Layouts is [outermost..innermost], so wrap in reverse.
		expr := fmt.Sprintf("page%d.%s()", ssrIndex(r, m), pageSymbol(r))
		for i := len(r.Layouts) - 1; i >= 0; i-- {
			l := r.Layouts[i]
			expr = fmt.Sprintf("layout%d.%s(%s)", layoutIndex(layouts, l.SourceFile), layoutSymbol(l.SourceFile), expr)
		}
		fmt.Fprintf(&b, "\t\treturn %s, nil\n\t}\n", expr)
	}
	fmt.Fprintf(&b, "\treturn nil, fmt.Errorf(%q, r.ID)\n", "routes: SSRPage: no component mapped for route %s (check that the page file exists and exports the expected templ component)")
	b.WriteString("}\n")

	formatted, err := format.Source([]byte(b.String()))
	if err != nil {
		// The generator itself produced invalid Go — always a bug here,
		// never a user-input condition.
		return nil, fmt.Errorf("codegen: generated source does not format (generator bug): %w", err)
	}
	return formatted, nil
}

// templImportPath returns the Go import path of the templ-generated
// package containing an SSR route's page: the page's directory relative to
// module root. The templ files declare `package app`, so every directory
// under app/ compiles to its own go-meta/app/<dir> package.
func templImportPath(r routing.Route) string {
	dir := path.Dir(r.SourceFile)
	if dir == "." || dir == "/" {
		return "go-meta/app"
	}
	return "go-meta/app/" + dir
}

// layoutImportPath returns the Go import path of the package containing a
// layout's templ-generated component. Like pages, each app-tree directory
// is its own package: root layout.templ lives in go-meta/app, a nested
// docs/layout.templ in go-meta/app/docs.
func layoutImportPath(sourceFile string) string {
	return templImportPath(routing.Route{SourceFile: sourceFile})
}

// ssrIndex is the manifest-order index of an SSR route, used for its
// deterministic generated alias.
// layoutIndex returns the import alias index for a layout source file in the
// sorted layout list. Layout aliases are deterministic: the layout list is
// sorted by source path, and the alias index is its position.
func layoutIndex(layoutSources []string, sourceFile string) int {
	for i, s := range layoutSources {
		if s == sourceFile {
			return i
		}
	}
	// Unreachable: layoutSources always comes from the manifest's own routes.
	return 0
}

func ssrIndex(r routing.Route, m routing.Manifest) int {
	n := 0
	for _, c := range m.Routes {
		if c.ID == r.ID && c.SourceFile == r.SourceFile {
			return n
		}
		if c.Mode == routing.ModeSSR {
			n++
		}
	}
	return n
}

// verifySymbols confirms every SSR route's templ source declares the expected
// component symbol, so a missing or misnamed symbol fails generation with an
// error naming the source file (C09: build error names source file; no
// runtime panic for missing generated bindings). Runs at generation time only.
// VerifySymbols checks that each SSR page source declares the templ component
// RoutesFile will reference, so a missing or misnamed symbol fails generation
// with an error naming the offending source file instead of surfacing later
// as an undefined-reference build error in generated/routes_gen.go.
func VerifySymbols(fsys fs.FS, m routing.Manifest) error {
	for _, r := range m.Routes {
		if r.Mode != routing.ModeSSR {
			continue
		}
		src, err := fs.ReadFile(fsys, r.SourceFile)
		if err != nil {
			return fmt.Errorf("routes: read %s: %w", r.SourceFile, err)
		}
		if !strings.Contains(string(src), "templ "+pageSymbol(r)+"(") {
			return fmt.Errorf("routes: %s: no templ component named %s found; declare `templ %s()` in the page file", r.SourceFile, pageSymbol(r), pageSymbol(r))
		}
	}
	for _, l := range layoutSources(m) {
		src, err := fs.ReadFile(fsys, l)
		if err != nil {
			return fmt.Errorf("routes: read %s: %w", l, err)
		}
		if !strings.Contains(string(src), "templ "+layoutSymbol(l)+"(") {
			return fmt.Errorf("routes: %s: no templ component named %s found; declare `templ %s(templ.Component)` in the layout file", l, layoutSymbol(l), layoutSymbol(l))
		}
	}
	return nil
}

// layoutSources returns every SSR layout source file in the manifest,
// deduplicated.
func layoutSources(m routing.Manifest) []string {
	seen := map[string]bool{}
	var out []string
	for _, r := range m.Routes {
		if r.Mode != routing.ModeSSR {
			continue
		}
		for _, l := range r.Layouts {
			if l.Mode != routing.ModeSSR {
				continue
			}
			if seen[l.SourceFile] {
				continue
			}
			seen[l.SourceFile] = true
			out = append(out, l.SourceFile)
		}
	}
	slices.Sort(out)
	return out
}

// layoutSymbol derives the templ component symbol for a layout source
// file: the root layout.templ -> Layout, nested docs/layout.templ ->
// DocsLayout.
func layoutSymbol(sourceFile string) string {
	dir := path.Dir(sourceFile)
	if dir == "." || dir == "/" {
		return "Layout"
	}
	parts := strings.Split(dir, "/")
	name := ""
	for _, p := range parts {
		if p == "" {
			continue
		}
		name += strings.ToUpper(p[:1]) + p[1:]
	}
	return name + "Layout"
}

// pageSymbol derives the templ component symbol name for a page source
// file: the Pascal-cased directory name (root page.templ -> Page,
// about/page.templ -> About, dashboard/settings/page.svelte ->
// DashboardSettings).
func pageSymbol(r routing.Route) string {
	dir := path.Dir(r.SourceFile)
	if dir == "." || dir == "/" {
		dir = ""
	}
	parts := strings.Split(dir, "/")
	name := ""
	for _, p := range parts {
		if p == "" {
			continue
		}
		// Upper-case first letter; leave the rest as-is. Directory names
		// are already validated to be URL-safe single segments.
		name += strings.ToUpper(p[:1]) + p[1:]
	}
	if name == "" {
		name = "Page"
	}
	return name
}

func writeRouteLiteral(b *strings.Builder, r routing.Route) {
	fmt.Fprintf(b, "\t\t{ID: %q, Path: %q, SourceFile: %q, Mode: %q",
		r.ID, r.Path, r.SourceFile, r.Mode)
	if len(r.Layouts) == 0 {
		b.WriteString("},\n")
		return
	}
	b.WriteString(", Layouts: []routing.Layout{\n")
	for _, l := range r.Layouts {
		fmt.Fprintf(b, "\t\t\t{ID: %q, SourceFile: %q, Mode: %q},\n",
			l.ID, l.SourceFile, l.Mode)
	}
	b.WriteString("\t\t}},\n")
}

// WriteRoutesFile generates and writes generated/routes_gen.go beneath dir.
// The caller passes the repo root; the output path is fixed by the
// generator, matching the blueprint's artifact location.
func WriteRoutesFile(dir string, m routing.Manifest) error {
	src, err := RoutesFile(m)
	if err != nil {
		return err
	}
	dst := filepath.Join(dir, "generated", "routes_gen.go")
	if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
		return fmt.Errorf("codegen: create generated directory: %w", err)
	}
	if err := os.WriteFile(dst, src, 0o644); err != nil {
		return fmt.Errorf("codegen: write %s: %w", dst, err)
	}
	return nil
}
